3	import { z } from "zod";
4	import { revalidatePath } from "next/cache";
5	import { requireRole } from "@/lib/auth";
6	import { createAdminClient } from "@/lib/supabase/admin";
7	import { getPayments } from "@/lib/integrations/payments";
8	import {
9	  providerDecisionSchema,
10	  type ProviderDecision,
11	} from "@/lib/validation/schemas";
12	import { type ProviderStatus, type BgCheckStatus } from "@/lib/supabase/types";
13	
14	const OUTCOME: Record<
15	  ProviderDecision["decision"],
16	  { status: ProviderStatus; bg_check_status?: BgCheckStatus }
17	> = {
18	  approve: { status: "approved", bg_check_status: "clear" },
19	  reject: { status: "rejected" },
20	  suspend: { status: "suspended" },
21	};
22	
23	/**
24	 * Admin decision on a provider: approve (→ clears the background check),
25	 * reject, or suspend. Role-guarded; writes via the service-role client.
26	 */
27	export async function decideProvider(
28	  input: ProviderDecision,
29	): Promise<{ ok: boolean; error?: string }> {
30	  await requireRole("admin");
31	
32	  const parsed = providerDecisionSchema.safeParse(input);
33	  if (!parsed.success) return { ok: false, error: "Invalid request." };
34	
35	  const outcome = OUTCOME[parsed.data.decision];
36	  const admin = createAdminClient();
37	  const { error } = await admin
38	    .from("providers")
39	    .update(outcome)
40	    .eq("id", parsed.data.providerId);
41	
42	  if (error) return { ok: false, error: "Could not update the listener." };
43	  revalidatePath("/admin/providers");
44	  return { ok: true };
45	}
46	
47	/**
48	 * Run the weekly payout job (mock): aggregate the period's session earnings +
49	 * tips into payout rows. Admin-only; returns how many payouts were created.
50	 */
51	export async function runWeeklyPayouts(): Promise<{ count: number }> {
52	  await requireRole("admin");
53	  const payments = getPayments();
54	  const { payouts } = await payments.runWeeklyPayouts();
55	  revalidatePath("/admin/providers");
56	  revalidatePath("/provider/dashboard");
57	  return { count: payouts.length };
58	}
59	
60	/** Mark a report as reviewed (admin only). */
61	export async function resolveReport(
62	  reportId: string,
63	): Promise<{ ok: boolean }> {
64	  await requireRole("admin");
65	  if (!z.string().uuid().safeParse(reportId).success) return { ok: false };
66	  const admin = createAdminClient();
67	  const { error } = await admin
68	    .from("reports")
69	    .update({ status: "reviewed" })
70	    .eq("id", reportId);
71	  if (error) return { ok: false };
72	  revalidatePath("/admin/reports");
73	  return { ok: true };
74	}
75	
76	const suspendSchema = z.object({
77	  userId: z.string().uuid(),
78	  suspended: z.boolean(),
79	});
80	
81	/**
82	 * Suspend or reinstate a user (admin only). Sets profiles.is_suspended; if the
83	 * user is a provider, also flips their provider status (suspended ⇄ approved)
84	 * so they leave / re-enter browse. Writes via the service-role client.
85	 */
86	export async function setUserSuspended(input: {
87	  userId: string;
88	  suspended: boolean;
89	}): Promise<{ ok: boolean }> {
90	  await requireRole("admin");
91	  const parsed = suspendSchema.safeParse(input);
92	  if (!parsed.success) return { ok: false };
93	  const { userId, suspended } = parsed.data;
94	
95	  const admin = createAdminClient();
96	  const { data: target } = await admin
97	    .from("profiles")
98	    .select("role")
99	    .eq("id", userId)
100	    .maybeSingle();
101	  if (!target) return { ok: false };
102	
103	  const { error } = await admin
104	    .from("profiles")
105	    .update({ is_suspended: suspended })
106	    .eq("id", userId);
107	  if (error) return { ok: false };
108	
109	  if (target.role === "provider") {
110	    await admin
111	      .from("providers")
112	      .update({ status: suspended ? "suspended" : "approved" })
113	      .eq("id", userId);
114	  }
115	
116	  revalidatePath("/admin/users");
117	  revalidatePath("/admin/reports");
118	  return { ok: true };
119	}
